void loadAppSettings() {
  prefs.begin("wazehud", true);
  settings.mirrorHud = prefs.getBool("mirror", false);
  settings.nightMode = prefs.getBool("night", true);
  settings.showRoad = prefs.getBool("road", true);
  settings.showRoute = prefs.getBool("route", true);
  settings.showEta = prefs.getBool("eta", true);
  settings.showSpeedLimit = prefs.getBool("limit", true);
  settings.showLanes = prefs.getBool("lane", true);
  settings.useMph = prefs.getBool("mph", false);
  settings.alertPolice = prefs.getBool("a_police", true);
  settings.alertCamera = prefs.getBool("a_camera", true);
  settings.alertCrash = prefs.getBool("a_crash", true);
  settings.alertTraffic = prefs.getBool("a_traffic", true);
  settings.alertRoadworks = prefs.getBool("a_work", true);
  settings.alertHazard = prefs.getBool("a_hazard", true);
  settings.alertSigns = prefs.getBool("a_signs", true);
  settings.autoUpdateCheck = prefs.getBool("autoupdate", true);
  settings.standbyClock = prefs.getBool("sb_on", true);
  settings.sbLunar = prefs.getBool("sb_lunar", true);
  settings.sbTemp = prefs.getBool("sb_temp", true);
  settings.wxCity = constrain((int)prefs.getUChar("wx_city", 0), 0, WX_CITY_COUNT - 1);
  settings.brightness = constrain((int)prefs.getUChar("bright", 100), 20, 100);
  settings.hudStyle = constrain((int)prefs.getUChar("layout", 3), 0, 5);
  bool fullHudMigrated = prefs.getBool("full150", false);
  prefs.end();

  // v1.5.0 switches existing devices to the finalized Full HUD exactly once.
  if (!fullHudMigrated) {
    settings.hudStyle = 3;
    prefs.begin("wazehud", false);
    prefs.putUChar("layout", 3);
    prefs.putBool("full150", true);
    prefs.end();
  }
}

void saveAppSettings() {
  prefs.begin("wazehud", false);
  prefs.putBool("mirror", settings.mirrorHud);
  prefs.putBool("night", settings.nightMode);
  prefs.putBool("road", settings.showRoad);
  prefs.putBool("route", settings.showRoute);
  prefs.putBool("eta", settings.showEta);
  prefs.putBool("limit", settings.showSpeedLimit);
  prefs.putBool("lane", settings.showLanes);
  prefs.putBool("mph", settings.useMph);
  prefs.putBool("a_police", settings.alertPolice);
  prefs.putBool("a_camera", settings.alertCamera);
  prefs.putBool("a_crash", settings.alertCrash);
  prefs.putBool("a_traffic", settings.alertTraffic);
  prefs.putBool("a_work", settings.alertRoadworks);
  prefs.putBool("a_hazard", settings.alertHazard);
  prefs.putBool("a_signs", settings.alertSigns);
  prefs.putBool("autoupdate", settings.autoUpdateCheck);
  prefs.putBool("sb_on", settings.standbyClock);
  prefs.putBool("sb_lunar", settings.sbLunar);
  prefs.putBool("sb_temp", settings.sbTemp);
  prefs.putUChar("wx_city", settings.wxCity);
  prefs.putUChar("bright", settings.brightness);
  prefs.putUChar("layout", settings.hudStyle);
  prefs.end();
}


