void drawHud() {
  ensureHudScreen();

  // Data freshness: never present a frozen speed/arrow as live data.
  const uint32_t age = millis() - hud.updatedAt;
  const bool lost = !hud.valid || age > HUD_TIMEOUT_MS;
  const bool stale = lost || age > HUD_STALE_MS;
  const bool nav = hud.navActive && !lost;

  // Mirror / brightness are applied while flushing pixels, so a change needs a
  // full-screen repaint now that unchanged widgets are no longer redrawn.
  static uint16_t lastFlushSig = 0xFFFF;
  uint16_t flushSig = (uint16_t)((settings.mirrorHud ? 1 : 0) | (settings.brightness << 1));
  if (flushSig != lastFlushSig) {
    lastFlushSig = flushSig;
    lv_obj_invalidate(lv_scr_act());
  }

  const char *title = lost ? "LINK LOST" : (nav ? maneuverInstruction(hud.turn) : "Không dẫn đường");
  setLabelText(uiTitle, title);

  String spd = lost ? String("--") : String(settings.useMph ? (int)roundf(max(0, hud.speed) * 0.621371f) : max(0, hud.speed));
  setLabelText(uiSpeed, spd.c_str());
  setLabelText(uiSpeedUnit, settings.useMph ? "mph" : "km/h");

  uint32_t speedRgb = 0xF5F8FF;
  if (settings.hudStyle == 4) speedRgb = 0x39E889;      // Sport theme
  if (stale) speedRgb = 0x8C9CB0;                       // old data: grey
  else if (hud.overSpeed) speedRgb = 0xFF453A;
  static uint32_t lastSpeedRgb = 0;
  if (speedRgb != lastSpeedRgb) {
    lastSpeedRgb = speedRgb;
    lv_obj_set_style_text_color(uiSpeed, lc(speedRgb), 0);
  }

  int shownLimit = hud.speedLimit > 0 ? (settings.useMph ? (int)roundf(hud.speedLimit * 0.621371f) : hud.speedLimit) : 0;
  String limit = shownLimit > 0 ? String(shownLimit) : "--";
  setLabelText(uiLimitText, limit.c_str());
  setHidden(uiLimitCircle, lost || !(settings.showSpeedLimit && hud.speedLimit > 0));

  // Maneuver / lane / alert canvases are repainted only when their input changes.
  static TurnType lastTurn = TURN_STRAIGHT;
  if (hudCanvasDirty || lastTurn != hud.turn) {
    drawTurnOnCanvas(uiManeuverCanvas, hud.turn, false);
    drawLaneOnCanvas();
    lastTurn = hud.turn;
  }
  setHidden(uiManeuverCanvas, !nav);
  setLabelText(uiDistance, nav ? formatDistance(hud.distanceM).c_str() : "");

  String eta = (nav && settings.showEta && hud.eta.length()) ? hud.eta : String("--:--");
  setLabelText(uiEta, eta.c_str());

  setHidden(uiLaneCanvas, !nav || !settings.showLanes);

  String road = settings.showRoad ? cleanDisplayText(hud.road, 18) : String("");
  if (!road.length() && settings.showRoute) road = cleanDisplayText(hud.route, 18);
  setLabelText(uiRoad, road.c_str());

  const bool alertOn = !lost && hud.alertCode != 0 && alertEnabled(hud.alert);
  static uint32_t lastAlertKey = 0xFFFFFFFF;
  uint32_t alertKey = alertOn
      ? ((uint32_t)hud.alertCode | ((uint32_t)(hud.alertSeverity & 0x7) << 8) |
         ((uint32_t)(hud.alertValue & 0x3FF) << 12))
      : 0;
  if (hudCanvasDirty || alertKey != lastAlertKey) {
    drawAlertOnCanvas();
    lastAlertKey = alertKey;
  }
  hudCanvasDirty = false;
  setHidden(uiAlertCanvas, !alertOn);
  setHidden(uiAlertLabel, !alertOn);
  setHidden(uiAlertDistance, !alertOn);
  if (alertOn) {
    String al = String(hlpAlertLabel(hud.alertCode));
    if (al.length() > 10) al = al.substring(0, 10);
    setLabelText(uiAlertLabel, al.c_str());
    setLabelText(uiAlertDistance, formatDistance(hud.alertDistanceM).c_str());
  }

  String remain = (nav && hud.remainingKm > 0) ? (String(hud.remainingKm, 1) + " km") : String("--");
  setLabelText(uiRemain, remain.c_str());

  int nextLimit = hud.nextSpeedLimit > 0 ? hud.nextSpeedLimit : 0;
  bool showNext = !lost && settings.showSpeedLimit && nextLimit > 0 && nextLimit != hud.speedLimit;
  setHidden(uiNextCaption, !showNext);
  setHidden(uiNextLimitCircle, !showNext);
  setHidden(uiNextDistance, !showNext);
  if (showNext) {
    int shownNext = settings.useMph ? (int)roundf(nextLimit * 0.621371f) : nextLimit;
    String ns = String(shownNext);
    setLabelText(uiNextLimitText, ns.c_str());
    setLabelText(uiNextDistance, compactDistance(hud.nextSpeedDistanceM).c_str());
  }

  // Six Studio themes use the same proven LVGL object tree, changing emphasis
  // and information density instead of allocating new screens.
  const uint8_t style = settings.hudStyle;
  const bool navFocus = style == 1;
  const bool minimal = style == 2;
  const bool full = style == 3;
  const bool sport = style == 4;
  const bool classic = style == 5;

  setHidden(uiEtaCaption, minimal || classic);
  setHidden(uiEta, minimal || classic);
  setHidden(uiRoad, minimal || sport);
  setHidden(uiLaneCanvas, !nav || !settings.showLanes || classic);
  if (minimal || classic) {
    setHidden(uiRemainCaption, true);
    setHidden(uiRemain, true);
    setHidden(uiNextCaption, true);
    setHidden(uiNextLimitCircle, true);
    setHidden(uiNextDistance, true);
  }
  if (navFocus) {
    setHidden(uiRemainCaption, true);
    setHidden(uiRemain, true);
  }
  if (classic) lv_obj_set_style_text_color(uiTitle, lc(0xF5F8FF), 0);

  const bool showThen = nav && hud.hasNextTurn && !minimal && !classic;
  setHidden(uiThenCaption, !showThen);
  setHidden(uiThenArrow, !showThen);
  if (showThen) setLabelText(uiThenArrow, turnGlyph(hud.nextTurn));
  const bool showExit = nav && hud.turn == TURN_ROUNDABOUT && hud.exitNumber > 0;
  setHidden(uiExitNum, !showExit);
  if (showExit) setLabelText(uiExitNum, String((int)hud.exitNumber).c_str());
  if (full) {
    // Full HUD keeps every enabled data block visible.
  }

  String clk = currentClockText();
  setLabelText(uiClock, clk.c_str());

  refreshStatusDots();
  lvUiPump();
}

