String studioSettingsJson() {
  // Compact keys keep the characteristic within GATT value limits. The Web Studio
  // writes the main and standby groups separately so each write stays small.
  JsonDocument d;
  d["m"] = settings.mirrorHud;
  d["n"] = settings.nightMode;
  d["b"] = settings.brightness;
  d["road"] = settings.showRoad;
  d["route"] = settings.showRoute;
  d["eta"] = settings.showEta;
  d["limit"] = settings.showSpeedLimit;
  d["lane"] = settings.showLanes;
  d["mph"] = settings.useMph;
  d["p"] = settings.alertPolice;
  d["cam"] = settings.alertCamera;
  d["cr"] = settings.alertCrash;
  d["tr"] = settings.alertTraffic;
  d["wrk"] = settings.alertRoadworks;
  d["haz"] = settings.alertHazard;
  d["sg"] = settings.alertSigns;
  d["au"] = settings.autoUpdateCheck;
  d["style"] = settings.hudStyle;
  d["sb"] = settings.standbyClock;
  d["sl"] = settings.sbLunar;
  d["st"] = settings.sbTemp;
  d["wc"] = settings.wxCity;
  String out;
  serializeJson(d, out);
  return out;
}

String studioInfoJson() {
  JsonDocument d;
  d["name"] = BLE_DEVICE_NAME;
  d["fw"] = FW_VERSION;
  d["mac"] = bleLocalAddress;
  d["screen"] = "ILI9341 320x240";
  d["renderer"] = "lvgl";
  d["ble"] = "nimble";
  String out;
  serializeJson(d, out);
  return out;
}

String studioStatusJson() {
  JsonDocument d;
  d["fw"] = FW_VERSION;
  d["wifi"] = WiFi.status() == WL_CONNECTED;
  d["ssid"] = WiFi.status() == WL_CONNECTED ? WiFi.SSID() : wifiSSID;
  d["ip"] = currentIpString();
  d["hlp"] = bleHlpReady;
  d["hud"] = hud.valid && (millis() - hud.updatedAt <= HUD_TIMEOUT_MS);
  d["ota"] = otaStatus;
  d["pct"] = otaPercent;
  d["heap"] = (uint32_t)ESP.getFreeHeap();
  d["rssi"] = WiFi.status() == WL_CONNECTED ? WiFi.RSSI() : 0;
  d["msg"] = studioMessage;
  d["upd"] = updateAvailable;
  d["chk"] = latestVersion.length() > 0;
  String out;
  serializeJson(d, out);
  return out;
}

String studioHudJson() {
  JsonDocument d;
  bool fresh = hud.valid && (millis() - hud.updatedAt <= HUD_TIMEOUT_MS);
  d["v"] = fresh ? 1 : 0;
  d["s"] = hud.speed;
  d["l"] = hud.speedLimit;
  d["o"] = hud.overSpeed ? 1 : 0;
  d["t"] = (int)hud.turn;
  d["d"] = hud.distanceM;

  String road = cleanText(hud.road);
  if (road.length() > 24) road = road.substring(0, 24);
  d["r"] = road;
  d["e"] = hud.eta;
  d["rm"] = max(0, (int)(hud.remainingKm * 1000.0f + 0.5f));

  d["a"] = hud.alertCode;
  d["ad"] = hud.alertDistanceM;
  d["av"] = hud.alertValue;
  d["as"] = hud.alertSeverity;
  d["ac"] = hud.alertCount;
  d["nl"] = hud.nextSpeedLimit;
  d["nd"] = hud.nextSpeedDistanceM;

  String out;
  serializeJson(d, out);
  return out;
}

void publishStudioHud(bool notifyHud) {
  if (!studioHudCharacteristic) return;
  String v = studioHudJson();
  studioHudCharacteristic->setValue((uint8_t*)v.c_str(), v.length());
  if (notifyHud) studioHudCharacteristic->notify();
}

void publishStudioState(bool notifyStatus) {
  if (studioInfoCharacteristic) {
    String v = studioInfoJson();
    studioInfoCharacteristic->setValue((uint8_t*)v.c_str(), v.length());
  }
  if (studioSettingsCharacteristic) {
    String v = studioSettingsJson();
    studioSettingsCharacteristic->setValue((uint8_t*)v.c_str(), v.length());
  }
  if (studioStatusCharacteristic) {
    String v = studioStatusJson();
    studioStatusCharacteristic->setValue((uint8_t*)v.c_str(), v.length());
    if (notifyStatus) studioStatusCharacteristic->notify();
  }
  publishStudioHud(false);
}

class StudioWriteCallbacks : public NimBLECharacteristicCallbacks {
 public:
  explicit StudioWriteCallbacks(uint8_t eventType) : type(eventType) {}

  void onWrite(NimBLECharacteristic *characteristic) override {
    if (!studioRxQueue) return;

    auto value = characteristic->getValue();
    if (value.length() == 0 || value.length() > sizeof(StudioRxEvent::bytes)) return;

    StudioRxEvent ev;
    ev.type = type;
    ev.length = (uint16_t)value.length();
    memcpy(ev.bytes, value.data(), ev.length);

    // Never parse JSON, change Wi-Fi or render LVGL on the NimBLE host task.
    xQueueSend(studioRxQueue, &ev, 0);
  }

 private:
  uint8_t type;
};

void resetStudioSettingsToDefaults() {
  settings.mirrorHud = false;
  settings.nightMode = true;
  settings.showRoad = true;
  settings.showRoute = true;
  settings.showEta = true;
  settings.showSpeedLimit = true;
  settings.showLanes = true;
  settings.useMph = false;
  settings.alertPolice = true;
  settings.alertCamera = true;
  settings.alertCrash = true;
  settings.alertTraffic = true;
  settings.alertRoadworks = true;
  settings.alertHazard = true;
  settings.alertSigns = true;
  settings.autoUpdateCheck = true;
  settings.brightness = 100;
  settings.hudStyle = 3;
  settings.standbyClock = true;
  settings.sbLunar = true;
  settings.sbTemp = true;
  settings.wxCity = 0;
  wxTempC = NAN;
  wxCode = -1;
  wxTried = false;
  wxDirty = true;
  saveAppSettings();
}

void applyStudioSettings(const String &payload) {
  JsonDocument d;
  if (deserializeJson(d, payload)) {
    studioMessage = "settings_json_error";
    return;
  }

  if (!d["m"].isNull()) settings.mirrorHud = (bool)d["m"];
  if (!d["n"].isNull()) settings.nightMode = (bool)d["n"];
  if (!d["b"].isNull()) settings.brightness = constrain((int)d["b"], 20, 100);
  if (!d["road"].isNull()) settings.showRoad = (bool)d["road"];
  if (!d["route"].isNull()) settings.showRoute = (bool)d["route"];
  if (!d["eta"].isNull()) settings.showEta = (bool)d["eta"];
  if (!d["limit"].isNull()) settings.showSpeedLimit = (bool)d["limit"];
  if (!d["lane"].isNull()) settings.showLanes = (bool)d["lane"];
  if (!d["mph"].isNull()) settings.useMph = (bool)d["mph"];
  if (!d["style"].isNull()) settings.hudStyle = constrain((int)d["style"], 0, 5);
  if (!d["p"].isNull()) settings.alertPolice = (bool)d["p"];
  if (!d["cam"].isNull()) settings.alertCamera = (bool)d["cam"];
  if (!d["cr"].isNull()) settings.alertCrash = (bool)d["cr"];
  if (!d["tr"].isNull()) settings.alertTraffic = (bool)d["tr"];
  if (!d["wrk"].isNull()) settings.alertRoadworks = (bool)d["wrk"];
  if (!d["haz"].isNull()) settings.alertHazard = (bool)d["haz"];
  if (!d["sg"].isNull()) settings.alertSigns = (bool)d["sg"];
  if (!d["au"].isNull()) settings.autoUpdateCheck = (bool)d["au"];
  if (!d["sb"].isNull()) settings.standbyClock = (bool)d["sb"];
  if (!d["sl"].isNull()) settings.sbLunar = (bool)d["sl"];
  if (!d["st"].isNull()) settings.sbTemp = (bool)d["st"];
  if (!d["wc"].isNull()) {
    uint8_t city = (uint8_t)constrain(d["wc"].as<int>(), 0, WX_CITY_COUNT - 1);
    if (city != settings.wxCity) {
      settings.wxCity = city;
      wxTempC = NAN;
      wxCode = -1;
      wxTried = false;
      wxDirty = true;
    }
  }

  saveAppSettings();
  studioMessage = "settings_saved";
  hudRenderValid = false;
  if (hud.valid) {
    drawHud();
    lv_obj_invalidate(lv_scr_act());
    lvUiPump();
  } else {
    drawWaiting();
  }
}

void applyStudioWiFi(const String &payload) {
  JsonDocument d;
  if (deserializeJson(d, payload)) {
    studioMessage = "wifi_json_error";
    return;
  }

  String ssid = String((const char*)(d["ssid"] | ""));
  String pass = String((const char*)(d["pass"] | ""));
  ssid.trim();

  if (!ssid.length() || ssid.length() > 32 || pass.length() > 63) {
    studioMessage = "wifi_invalid";
    return;
  }

  prefs.begin("wazehud", false);
  prefs.putString("ssid", ssid);
  prefs.putString("pass", pass);
  prefs.end();

  wifiSSID = ssid;
  wifiPASS = pass;
  studioMessage = "wifi_saved_rebooting";
  publishStudioState(true);
  studioRestartAt = millis() + 1200;
}

void applyStudioCommand(const String &payload) {
  JsonDocument d;
  if (deserializeJson(d, payload)) {
    studioMessage = "command_json_error";
    return;
  }

  String cmd = String((const char*)(d["cmd"] | ""));
  cmd.toLowerCase();

  if (cmd == "refresh") {
    studioMessage = "ready";
  } else if (cmd == "check_update") {
    studioMessage = "checking_update";
    publishStudioState(true);
    checkForUpdate();
    studioMessage = updateAvailable ? "update_available" : updateMessage;
  } else if (cmd == "ota") {
    if (otaInProgress || otaRequested) {
      studioMessage = "ota_busy";
    } else {
      if (!updateAvailable && !checkForUpdate()) {
        studioMessage = updateMessage;
      } else if (!updateAvailable) {
        studioMessage = "already_latest";
      } else {
        otaStatus = "queued";
        updateMessage = "Đã nhận lệnh cập nhật v" + latestVersion;
        otaRequestedAt = millis();
        otaRequested = true;
        studioMessage = "ota_queued";
      }
    }
  } else if (cmd == "reboot") {
    studioMessage = "rebooting";
    publishStudioState(true);
    studioRestartAt = millis() + 700;
  } else if (cmd == "defaults") {
    resetStudioSettingsToDefaults();
    studioMessage = "defaults_restored";
    hudRenderValid = false;
    if (hud.valid) drawHud(); else drawWaiting();
  } else {
    studioMessage = "unknown_command";
  }
}

void processStudioInput() {
  if (!studioRxQueue) return;

  StudioRxEvent ev;
  bool changed = false;

  while (xQueueReceive(studioRxQueue, &ev, 0) == pdTRUE) {
    String payload;
    payload.reserve(ev.length);
    for (uint16_t i = 0; i < ev.length; ++i) payload += (char)ev.bytes[i];

    if (ev.type == 1) applyStudioSettings(payload);
    else if (ev.type == 2) applyStudioWiFi(payload);
    else if (ev.type == 3) applyStudioCommand(payload);
    changed = true;
  }

  if (changed) publishStudioState(true);
}

class HudBleServerCallbacks : public NimBLEServerCallbacks {
  void onConnect(NimBLEServer *server) override {
    bleConnected = true;
    bleHlpReady = false;
    bleRxBuffer = "";
    if (bleRxQueue != nullptr) xQueueReset(bleRxQueue);
    lastBleDevNotify = 0;
    wifiUiDirty = true; // UI refresh is deferred to loop(); LVGL stays single-threaded.
    Serial.println("BLE HLP client connected");
  }

  void onDisconnect(NimBLEServer *server) override {
    bleConnected = false;
    bleHlpReady = false;
    bleRxBuffer = "";
    if (bleRxQueue != nullptr) xQueueReset(bleRxQueue);
    wifiUiDirty = true; // Never call LVGL directly from the NimBLE host task.
    NimBLEDevice::getAdvertising()->start();
    Serial.println("BLE HLP client disconnected; advertising restarted");
  }
};

class HudBleTxCallbacks : public NimBLECharacteristicCallbacks {
  void onWrite(NimBLECharacteristic *characteristic) override {
    // HLP/1 requires the GATT callback to return quickly. Copy the ATT chunk
    // into a bounded FreeRTOS queue; framing, JSON parsing and TFT rendering
    // happen later from loop().
    auto value = characteristic->getValue();
    String raw(value.c_str());

    if (raw.length() == 0 || raw.length() > sizeof(BleRxChunk::bytes) || bleRxQueue == nullptr) {
      bleRxDropped++;
      return;
    }

    BleRxChunk chunk;
    chunk.length = (uint16_t)raw.length();
    memcpy(chunk.bytes, raw.c_str(), chunk.length);

    if (xQueueSend(bleRxQueue, &chunk, 0) != pdTRUE) {
      bleRxDropped++;
    }
  }
};

void processBleLine(String payload) {
  payload.trim();
  if (!payload.length()) return;

  // applyHudPayload replies to ping before any TFT rendering.
  if (applyHudPayload(payload) && hud.valid) {
    drawHud();
    publishStudioHud(true);
  }
}

void processBleInput() {
  if (bleRxQueue == nullptr) return;

  BleRxChunk chunk;
  while (xQueueReceive(bleRxQueue, &chunk, 0) == pdTRUE) {
    for (uint16_t i = 0; i < chunk.length; i++) {
      char c = (char)chunk.bytes[i];

      if (c == '\n') {
        String payload = bleRxBuffer;
        bleRxBuffer = "";
        processBleLine(payload);
      } else if (c != '\r') {
        // HLP/1 frames are limited to 512 bytes.
        if (bleRxBuffer.length() < 512) {
          bleRxBuffer += c;
        } else {
          bleRxBuffer = "";
          bleRxDropped++;
        }
      }
    }
  }
}

void setupBLE() {
  bleRxQueue = xQueueCreate(16, sizeof(BleRxChunk));
  if (bleRxQueue == nullptr) {
    Serial.println("ERROR: cannot create BLE RX queue");
  }

  studioRxQueue = xQueueCreate(8, sizeof(StudioRxEvent));
  if (studioRxQueue == nullptr) {
    Serial.println("ERROR: cannot create Studio RX queue");
  }

  NimBLEDevice::init(BLE_DEVICE_NAME);
  NimBLEDevice::setMTU(185);

  NimBLEServer *bleServer = NimBLEDevice::createServer();
  bleServer->setCallbacks(new HudBleServerCallbacks());

  NimBLEService *service = bleServer->createService(BLE_SERVICE_UUID);

  // Android -> HUD. HLP/1 uses acknowledged writes.
  NimBLECharacteristic *tx = service->createCharacteristic(
    BLE_TX_UUID,
    NIMBLE_PROPERTY::WRITE
  );
  tx->setCallbacks(new HudBleTxCallbacks());

  // HUD -> Android. NimBLE automatically exposes CCCD for NOTIFY.
  bleNotifyCharacteristic = service->createCharacteristic(
    BLE_RX_UUID,
    NIMBLE_PROPERTY::NOTIFY
  );

  NimBLECharacteristic *caps = service->createCharacteristic(
    BLE_CAPS_UUID,
    NIMBLE_PROPERTY::READ
  );
  const char *capsJson = "{\"v\":1,\"caps\":{\"transport\":\"ble\",\"maxFrame\":512}}\n";
  caps->setValue((uint8_t*)capsJson, strlen(capsJson));

  service->start();

  // Separate Web Bluetooth configuration service.
  NimBLEService *studioService = bleServer->createService(STUDIO_SERVICE_UUID);

  studioInfoCharacteristic = studioService->createCharacteristic(
    STUDIO_INFO_UUID,
    NIMBLE_PROPERTY::READ
  );

  studioSettingsCharacteristic = studioService->createCharacteristic(
    STUDIO_SETTINGS_UUID,
    NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE
  );
  studioSettingsCharacteristic->setCallbacks(new StudioWriteCallbacks(1));

  NimBLECharacteristic *studioWifi = studioService->createCharacteristic(
    STUDIO_WIFI_UUID,
    NIMBLE_PROPERTY::WRITE
  );
  studioWifi->setCallbacks(new StudioWriteCallbacks(2));

  NimBLECharacteristic *studioCommand = studioService->createCharacteristic(
    STUDIO_COMMAND_UUID,
    NIMBLE_PROPERTY::WRITE
  );
  studioCommand->setCallbacks(new StudioWriteCallbacks(3));

  studioStatusCharacteristic = studioService->createCharacteristic(
    STUDIO_STATUS_UUID,
    NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY
  );

  studioHudCharacteristic = studioService->createCharacteristic(
    STUDIO_HUD_UUID,
    NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY
  );

  studioService->start();

  bleLocalAddress = String(NimBLEDevice::getAddress().toString().c_str());
  publishStudioState(false);

  // Keep the official HLP service UUID in the advertisement so WazeMod can
  // filter this device directly. Scan response carries the configured name.
  NimBLEAdvertising *advertising = NimBLEDevice::getAdvertising();
  advertising->addServiceUUID(BLE_SERVICE_UUID);
  advertising->setScanResponse(true);
  advertising->start();

  Serial.print("NimBLE HLP/1 + Studio advertising as WazeHUD, address: ");
  Serial.println(bleLocalAddress);
  Serial.print("Studio service: ");
  Serial.println(STUDIO_SERVICE_UUID);
}


int compareVersions(const String &a, const String &b) {
  int ia = 0, ib = 0;
  for (int part = 0; part < 4; ++part) {
    long va = 0, vb = 0;
    while (ia < (int)a.length() && !isDigit(a[ia])) ia++;
    while (ib < (int)b.length() && !isDigit(b[ib])) ib++;
    while (ia < (int)a.length() && isDigit(a[ia])) { va = va * 10 + (a[ia++] - '0'); }
    while (ib < (int)b.length() && isDigit(b[ib])) { vb = vb * 10 + (b[ib++] - '0'); }
    if (va < vb) return -1;
    if (va > vb) return 1;
  }
  return 0;
}

bool parseUpdateManifest(const String &url) {
  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  HTTPClient http;
  http.setUserAgent("ESP32-Waze-HUD/" + String(FW_VERSION));
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  http.setConnectTimeout(12000);
  http.setTimeout(15000);

  if (!http.begin(client, url)) return false;
  http.addHeader("Accept-Encoding", "identity");
  http.addHeader("Cache-Control", "no-cache");

  int code = http.GET();
  Serial.print("OTA manifest HTTP: ");
  Serial.println(code);
  if (code != HTTP_CODE_OK) {
    http.end();
    return false;
  }

  JsonDocument doc;
  DeserializationError err = deserializeJson(doc, *http.getStreamPtr());
  http.end();
  if (err) {
    Serial.print("OTA manifest JSON error: ");
    Serial.println(err.c_str());
    return false;
  }

  String version = String((const char*)(doc["version"] | ""));
  String urlValue = String((const char*)(doc["url"] | ""));
  size_t sizeValue = (size_t)(doc["size"] | 0);
  version.trim();
  urlValue.trim();
  if (version.startsWith("v")) version.remove(0, 1);

  if (!version.length() || !urlValue.length()) return false;
  latestVersion = version;
  latestFirmwareUrl = urlValue;
  latestFirmwareSize = sizeValue;
  return true;
}

bool parseGithubReleaseStream() {
  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(20000);

  HTTPClient http;
  http.setUserAgent("ESP32-Waze-HUD/" + String(FW_VERSION));
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  http.setConnectTimeout(15000);
  http.setTimeout(20000);

  String api = String("https://api.github.com/repos/") + GITHUB_REPO + "/releases/latest";
  if (!http.begin(client, api)) return false;

  http.addHeader("Accept", "application/vnd.github+json");
  http.addHeader("X-GitHub-Api-Version", "2022-11-28");
  http.addHeader("Accept-Encoding", "identity");

  int code = http.GET();
  Serial.print("OTA GitHub API HTTP: ");
  Serial.println(code);
  if (code != HTTP_CODE_OK) {
    http.end();
    return false;
  }

  // Filter the large GitHub response while parsing the network stream.
  JsonDocument filter;
  filter["tag_name"] = true;
  filter["assets"][0]["name"] = true;
  filter["assets"][0]["browser_download_url"] = true;
  filter["assets"][0]["size"] = true;

  JsonDocument doc;
  DeserializationError err = deserializeJson(
    doc,
    *http.getStreamPtr(),
    DeserializationOption::Filter(filter)
  );
  http.end();

  if (err) {
    Serial.print("OTA GitHub JSON error: ");
    Serial.println(err.c_str());
    return false;
  }

  latestVersion = String((const char*)(doc["tag_name"] | ""));
  if (latestVersion.startsWith("v")) latestVersion.remove(0, 1);

  JsonArray assets = doc["assets"].as<JsonArray>();
  for (JsonObject asset : assets) {
    String name = String((const char*)(asset["name"] | ""));
    if (name == "firmware.bin" || name.endsWith("-firmware.bin")) {
      latestFirmwareUrl = String((const char*)(asset["browser_download_url"] | ""));
      latestFirmwareSize = (size_t)(asset["size"] | 0);
      break;
    }
  }

  return latestVersion.length() && latestFirmwareUrl.length();
}

bool checkForUpdate() {
  updateAvailable = false;
  latestVersion = "";
  latestFirmwareUrl = "";
  latestFirmwareSize = 0;

  if (WiFi.status() != WL_CONNECTED) {
    updateMessage = "Wi-Fi chưa kết nối Internet";
    Serial.println("OTA check: Wi-Fi not connected");
    return false;
  }

  bool ok = parseUpdateManifest(OTA_MANIFEST_URL);
  if (!ok) {
    Serial.println("OTA manifest unavailable; falling back to GitHub API stream");
    ok = parseGithubReleaseStream();
  }

  if (!ok) {
    updateMessage = "Không đọc được thông tin bản cập nhật";
    return false;
  }

  int cmp = compareVersions(latestVersion, String(FW_VERSION));
  updateAvailable = cmp > 0;

  if (updateAvailable) {
    updateMessage = "Có bản v" + latestVersion;
  } else if (cmp == 0) {
    updateMessage = "Đang dùng bản mới nhất v" + String(FW_VERSION);
  } else {
    updateMessage = "Thiết bị mới hơn bản online (v" + latestVersion + ")";
  }

  Serial.print("OTA latest: v");
  Serial.print(latestVersion);
  Serial.print(", asset bytes=");
  Serial.println((unsigned long)latestFirmwareSize);
  return true;
}

bool installOnlineUpdate() {
  otaBytesWritten = 0;
  otaBytesTotal = 0;
  otaPercent = 0;

  if (WiFi.status() != WL_CONNECTED) {
    updateMessage = "OTA lỗi: Wi-Fi đã mất kết nối";
    otaStatus = "failed";
    return false;
  }

  if (!latestFirmwareUrl.length()) {
    if (!checkForUpdate() || !latestFirmwareUrl.length()) {
      otaStatus = "failed";
      return false;
    }
  }

  size_t freeSketch = ESP.getFreeSketchSpace();
  if (latestFirmwareSize > 0 && latestFirmwareSize > freeSketch) {
    updateMessage = "Firmware quá lớn cho OTA partition";
    otaStatus = "failed";
    Serial.print("OTA size too large. asset=");
    Serial.print((unsigned long)latestFirmwareSize);
    Serial.print(" free=");
    Serial.println((unsigned long)freeSketch);
    return false;
  }

  otaStatus = "downloading";
  updateMessage = "Đang tải firmware v" + latestVersion;
  drawOtaProgressScreen(0, "PREPARING UPDATE", true);

  Serial.print("OTA free sketch space: ");
  Serial.println((unsigned long)freeSketch);
  Serial.print("OTA URL: ");
  Serial.println(latestFirmwareUrl);

  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(30000);

  HTTPClient http;
  http.setUserAgent("ESP32-Waze-HUD/" + String(FW_VERSION));
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  http.setConnectTimeout(20000);
  http.setTimeout(30000);

  if (!http.begin(client, latestFirmwareUrl)) {
    updateMessage = "OTA lỗi: không mở được firmware URL";
    otaStatus = "failed";
    Serial.println("OTA download: http.begin failed");
    return false;
  }

  http.addHeader("Accept-Encoding", "identity");

  int code = http.GET();
  Serial.print("OTA download HTTP: ");
  Serial.println(code);

  if (code != HTTP_CODE_OK) {
    updateMessage = "OTA tải lỗi HTTP " + String(code);
    otaStatus = "failed";
    http.end();
    return false;
  }

  int contentLength = http.getSize();
  size_t expected = contentLength > 0 ? (size_t)contentLength : latestFirmwareSize;
  otaBytesTotal = expected;

  Serial.print("OTA content length: ");
  Serial.println(contentLength);

  if (expected > 0 && expected > freeSketch) {
    updateMessage = "Firmware vượt quá OTA partition";
    otaStatus = "failed";
    http.end();
    return false;
  }

  size_t beginSize = expected > 0 ? expected : UPDATE_SIZE_UNKNOWN;
  if (!Update.begin(beginSize)) {
    int errCode = Update.getError();
    updateMessage = "Update.begin lỗi " + String(errCode);
    otaStatus = "failed";
    Serial.print("Update.begin failed, code=");
    Serial.println(errCode);
    Update.printError(Serial);
    http.end();
    return false;
  }

  otaStatus = "writing";
  updateMessage = "Đang tải và cài đặt...";
  drawOtaProgressScreen(1, "DOWNLOADING + INSTALLING");

  WiFiClient *stream = http.getStreamPtr();
  uint8_t buffer[1024];
  size_t written = 0;
  bool streamOK = true;
  uint32_t lastDataAt = millis();
  uint32_t lastWebAt = 0;

  while ((expected > 0 && written < expected) ||
         (expected == 0 && http.connected())) {
    size_t available = stream->available();

    if (available > 0) {
      size_t want = min(available, sizeof(buffer));
      if (expected > 0) want = min(want, expected - written);

      size_t got = stream->readBytes(buffer, want);
      if (got == 0) {
        delay(1);
        continue;
      }

      size_t flashed = Update.write(buffer, got);
      if (flashed != got) {
        streamOK = false;
        Serial.print("OTA Update.write mismatch: ");
        Serial.print((unsigned long)flashed);
        Serial.print("/");
        Serial.println((unsigned long)got);
        break;
      }

      written += flashed;
      otaBytesWritten = written;
      lastDataAt = millis();

      uint8_t pct = 1;
      if (expected > 0) {
        // Reserve 100% for successful verification.
        size_t calcPct = (written * (size_t)99) / expected;
        if (calcPct > 99) calcPct = 99;
        pct = (uint8_t)calcPct;
      }
      otaPercent = pct;
      updateMessage = "Đang cập nhật " + String(pct) + "%";
      studioMessage = "ota_writing";
      drawOtaProgressScreen(pct, "DOWNLOADING + INSTALLING");
      if (millis() - lastStudioStatusNotify >= 500) {
        lastStudioStatusNotify = millis();
        publishStudioState(true);
      }
    } else {
      if (expected > 0 && written >= expected) break;
      if (!http.connected() && expected == 0) break;

      if (millis() - lastDataAt > 30000) {
        streamOK = false;
        updateMessage = "OTA timeout khi tải firmware";
        Serial.println("OTA stream timeout");
        break;
      }

      delay(1);
    }

    // Keep /update-status responsive during the otherwise blocking OTA stream.
    if (millis() - lastWebAt >= 120) {
      lastWebAt = millis();
      server.handleClient();
    }
    yield();
  }

  otaBytesWritten = written;

  Serial.print("OTA written: ");
  Serial.print((unsigned long)written);
  Serial.print("/");
  Serial.println((unsigned long)expected);

  bool lengthOK = expected == 0 || written == expected;

  if (!streamOK || !lengthOK) {
    int errCode = Update.getError();
    Update.abort();
    http.end();

    otaStatus = "failed";
    otaPercent = 0;
    updateMessage = "OTA ghi lỗi " + String(errCode) + " (" +
                    String((unsigned long)written) + "/" +
                    String((unsigned long)expected) + " bytes)";
    Serial.println(updateMessage);
    return false;
  }

  drawOtaProgressScreen(99, "VERIFYING FIRMWARE");
  otaPercent = 99;
  updateMessage = "Đang xác minh firmware...";

  bool endOK = Update.end(true);
  bool finished = Update.isFinished();
  http.end();

  if (!endOK || !finished) {
    int errCode = Update.getError();
    otaStatus = "failed";
    updateMessage = "OTA xác minh lỗi " + String(errCode);
    Serial.print("OTA verify failed, error=");
    Serial.println(errCode);
    Update.printError(Serial);
    return false;
  }

  otaPercent = 100;
  otaStatus = "success";
  studioMessage = "ota_success";
  updateMessage = "Cập nhật v" + latestVersion + " thành công";
  drawOtaProgressScreen(100, "UPDATE COMPLETE");

  Serial.println("OTA success; rebooting");
  return true;
}


